/**
 * @fileoverview Test the overriding of a deprecated method
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-deprecated-method-override'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-deprecated-method-override', rule, {

    valid: [
        {
            code: `
                
            `
        }
    ],

    invalid: [
        {
            settings: {
                extjs: {
                    fromVersion: '4',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',
                
                    // override with a Literal but no fixer should be offered
                    addClass: true,

                    // override with a FunctionalExpression
                    doComponentLayout: function () {
                        return this.callParent();
                    },

                    // override with a FunctionalExpression
                    forceComponentLayout: function () {
                        return this.callParent();
                    },

                    // override with MemberExpression
                    removeClass: Ext.emptyFn,

                    // override with ConditionalExpression
                    beforeDestroy: supportsIndexOf ? function(array, item) {
                        return 1;
                    } : function(array, item) {
                        return 2;
                    },

                    setAutoScroll: Ext.emptyFn,
                    setDocked: Ext.emptyFn,
                    setOverflowXY: Ext.emptyFn
                });
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    validate: function () {}
                });
                Ext.define('overrides.Model', {
                    override: 'Ext.data.TreeModel',
                    // should NOT offer a fix since the replacement you are trying to supply is not a method
                    validate: false
                });
            `,
            output: `
                Ext.define('MyCustomComponent', {
                    extend: 'Ext.Component',
                
                    // override with a Literal but no fixer should be offered
                    addClass: true,

                    // override with a FunctionalExpression
                    updateLayout: function () {
                        return this.callParent();
                    },

                    // override with a FunctionalExpression
                    updateLayout: function () {
                        return this.callParent();
                    },

                    // override with MemberExpression
                    removeCls: Ext.emptyFn,

                    // override with ConditionalExpression
                    onDestroy: supportsIndexOf ? function(array, item) {
                        return 1;
                    } : function(array, item) {
                        return 2;
                    },

                    setAutoScroll: Ext.emptyFn,
                    setDock: Ext.emptyFn,
                    setOverflowXY: Ext.emptyFn
                });
                Ext.define('User', {
                    extend: 'Ext.data.Model',
                    getValidation: function () {}
                });
                Ext.define('overrides.Model', {
                    override: 'Ext.data.TreeModel',
                    // should NOT offer a fix since the replacement you are trying to supply is not a method
                    validate: false
                });
            `,
            errors: [
                { message: /Override of deprecated method 'addClass' found for 'Ext.Component'.*/ },
                { message: /Override of deprecated method 'doComponentLayout' found for 'Ext.Component'.*/ },
                { message: /Override of deprecated method 'forceComponentLayout' found for 'Ext.Component'.*/ },
                { message: /Override of deprecated method 'removeClass' found for 'Ext.Component'.*/ },
                { message: /Override of deprecated method 'beforeDestroy' found for 'Ext.Component'.*/ },
                { message: /Override of deprecated method 'setAutoScroll' found for 'Ext.Component'.*/ },
                { message: /Override of deprecated method 'setDocked' found for 'Ext.Component'.*/ },
                { message: /Override of deprecated method 'setOverflowXY' found for 'Ext.Component'.*/ },
                { message: /Override of deprecated method 'validate' found for 'Ext.data.Model'.*/ },
                { message: /Override of deprecated method 'validate' found for 'Ext.data.TreeModel'.*/ }
            ],
        }
    ]
});
